package net.minecraft.nbt;import java.util.*;public class CompoundTag {public Map<String,Object> values=new HashMap<>();public boolean contains(String key){return values.containsKey(key);}public int getInt(String key){return ((Number)values.getOrDefault(key,0)).intValue();}public float getFloat(String key){return ((Number)values.getOrDefault(key,0)).floatValue();}public void putInt(String key,int value){values.put(key,value);}public void putFloat(String key,float value){values.put(key,value);}}